import{_t as e,it as t,n,rt as r}from"./chunks/framework.Bc6s-rUw.js";var i=JSON.parse(`{"title":"vex test reference","description":"","frontmatter":{},"headers":[],"relativePath":"references/vex-test-reference.md","filePath":"references/vex-test-reference.md"}`),a={name:`references/vex-test-reference.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="vex-test-reference" tabindex="-1"><code>vex test</code> reference <a class="header-anchor" href="#vex-test-reference" aria-label="Permalink to “vex test reference”">​</a></h1><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vex test [OPTIONS] [PATTERN]</span></span></code></pre></div><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to “Discovery”">​</a></h2><table tabindex="0"><thead><tr><th>File/function</th><th>Meaning</th></tr></thead><tbody><tr><td><code>*.test.vx</code>, <code>*_test.vx</code>, <code>*_bench.vx</code></td><td>Discoverable source under a selected directory</td></tr><tr><td><code>test_*</code>, <code>Test*</code></td><td>Test function</td></tr><tr><td><code>bench_*</code>, <code>Benchmark*</code></td><td>Benchmark function</td></tr></tbody></table><p><code>PATTERN</code> accepts an existing directory, an existing regular <code>.vx</code> file, or a quoted glob such as <code>&quot;lib/std/net/tests/*.test.vx&quot;</code>. Existing literal paths take precedence over glob syntax, including filenames containing brackets and directories whose names end in <code>.vx</code>. With no argument, discovery starts in the current directory.</p><p>A file glob can select any ordinary <code>.vx</code> filename. A matched directory selects its conventionally named test/benchmark sources recursively. Recursive <code>**</code> globs are supported. Automatic traversal skips generated runners, hidden directories, <code>target</code>, <code>node_modules</code>, <code>vex-builds</code> and <code>archived</code>. It does not follow discovered directory symlinks; pass a directory symlink explicitly to select that root. Source-file symlinks are accepted and deduplicated by their resolved path. Pipes, sockets and devices are never opened as test sources.</p><p>A missing explicit path, invalid/unmatched glob, or unreadable selected source is an error with a nonzero exit status, not an empty successful run. A real empty directory or a <code>--run</code> filter selecting no functions remains a valid empty selection. Neither is evidence that tests passed.</p><p>Accepted test signatures are zero arguments or one <code>&amp;TestCtx!</code> argument. Zero-argument <code>bool</code> uses <code>true</code> as success; integer status uses <code>0</code>; context tests use sealed <code>failed()</code>/<code>skipped()</code> state. Async tests are awaited from a generated async main. A discovered file with a custom <code>main</code> is rejected.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Purpose</th></tr></thead><tbody><tr><td><code>-q</code>, <code>--quiet</code></td><td>Zero-noise successful output</td></tr><tr><td><code>-v</code>, <code>--verbose</code></td><td>Detailed execution output</td></tr><tr><td><code>--run &lt;REGEX&gt;</code></td><td>Filter test names</td></tr><tr><td><code>--no-parallel</code></td><td>Serialize test files</td></tr><tr><td><code>--timeout &lt;SECONDS&gt;</code></td><td>Bound runtime for each generated test-file runner</td></tr><tr><td><code>--failfast</code></td><td>Stop after first failure</td></tr><tr><td><code>--short</code></td><td>Select short-mode behavior</td></tr><tr><td><code>--json</code></td><td>Structured result output</td></tr><tr><td><code>-O0</code> … <code>-O3</code></td><td>Generated runner optimization level</td></tr><tr><td><code>--analyze-comptime</code></td><td>Print comptime staging telemetry</td></tr><tr><td><code>--coverage</code></td><td>LLVM coverage run</td></tr><tr><td><code>--coverprofile &lt;FILE&gt;</code></td><td>Coverage output path</td></tr><tr><td><code>--covermode &lt;MODE&gt;</code></td><td><code>set</code>, <code>count</code>, or <code>atomic</code></td></tr><tr><td><code>--fuzz &lt;TARGET&gt;</code></td><td>Run a fuzz target</td></tr><tr><td><code>--fuzztime &lt;DURATION&gt;</code></td><td>Bound fuzz execution</td></tr></tbody></table><p>Benchmark-only options:</p><table tabindex="0"><thead><tr><th>Option</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--bench</code></td><td>Select benchmarks instead of tests</td></tr><tr><td><code>--benchtime &lt;DURATION&gt;</code></td><td>Target measurement duration (default <code>1s</code>)</td></tr><tr><td><code>--count &lt;N&gt;</code></td><td>Repeat benchmark measurement</td></tr><tr><td><code>--benchmem</code></td><td>Report allocation counters</td></tr></tbody></table><p>Use <code>vex test --help</code> as the authoritative flag list for the installed CLI. For tests, the runtime watchdog starts when the generated runner enters <code>main</code>; it covers the whole file, not a separate budget per function. Compilation has a separate 180-second watchdog and process startup has its own deadline. These are not charged to <code>--timeout</code>. Runtime timeout terminates the runner&#39;s process group, including its child processes.</p><p>Completed test results survive a later timeout: a reported <code>PASS</code>, <code>FAIL</code> or <code>SKIP</code> keeps its status and measured duration. Only tests without a complete result record receive <code>timeout</code>. The CLI retains partial stdout/stderr for diagnosis.</p><p>Test completion and process completion are separate. A file may print all its test results and then hang while waiting for detached tasks, or terminate abnormally during finalization. Such a run exits nonzero and reports a <strong>file execution error</strong>; it does not invent an additional failed test or rewrite completed outcomes. <code>--failfast</code> stops on file errors as well as test failures.</p><p>In <code>--json</code> output, <code>passed</code>, <code>failed</code>, <code>skipped</code>, <code>total</code> and <code>results</code> describe actual test functions. A skipped test has status <code>skip</code> and counts toward <code>skipped</code> and <code>total</code>, not <code>passed</code> or <code>failed</code>. An all-skipped run succeeds but is summarized as <code>SKIP</code>, not as evidence of passing tests. Calling <code>skip()</code> after <code>err()</code> does not suppress the failure.</p><p>The additive <code>file_errors</code> array contains objects with <code>file</code>, <code>status</code> (<code>timeout</code> or <code>runtime_error</code>), <code>message</code> and diagnostic <code>details</code>. It is empty on a clean run. Automation must check the CLI exit status and <code>file_errors</code>, not just <code>failed == 0</code>: all tests can pass while finalization fails. Compilation failures remain <code>compile_error</code> test results, not runtime timeouts.</p><p>The API reference for <code>TestCtx</code> and <code>BenchCtx</code> is on the <a href="/docs/std/testing"><code>testing</code> package page</a>.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};